  shape.holes.push(rectHole(HEAD_SLOT.x0, -HEAD_SLOT.z1, HEAD_SLOT.x1, -HEAD_SLOT.z0)); // (g)
  const body = extrudeFlat(shape, 2, bottomShellFill);
  body.position.y = -1;                  // shell spans groupY −1..+1
  addEdgedMesh(body, g);

  /* (a) central circular depression d44 — thin cylinder just below top surface */
  const depression = new THREE.Mesh(new THREE.CylinderGeometry(22, 22, 0.3, 48), bottomShellFill);
  depression.position.set(0, 0.8, 0);
  addEdgedMesh(depression, g);

  /* (c) four corner locating posts (r1.5, h1) protruding above the top */
  [[24, 24], [-24, 24], [24, -24], [-24, -24]].forEach(([x, z]) => {
    const post = new THREE.Mesh(new THREE.CylinderGeometry(1.5, 1.5, 1, 16), bottomShellFill);
    post.position.set(x, 1.5, z);
    addEdgedMesh(post, g);
  });

  /* (d) LIFTER — small protruding box, mid-front area */
  const lifter = new THREE.Mesh(new THREE.BoxGeometry(8, 1, 4), bottomShellFill);
  lifter.position.set(0, 1.5, -8);
  addEdgedMesh(lifter, g);

  /* (e) SHUTTER SPRING recess — thin sunken box at front edge middle */
  const spring = new THREE.Mesh(new THREE.BoxGeometry(10, 0.3, 4), bottomShellFill);
  spring.position.set(1, 0.8, -28);
  addEdgedMesh(spring, g);

  g.position.set(0, -1.5, 0);            // assembledY = −1.5
  return g;
}

/* ============================================================================
   3.2 / 3.5 DUST LINER — C-ring with rectangular head-window notch
   ============================================================================ */
function linerShape() {
  const R = 28;                          // outer radius
  const a = Math.acos(22 / R);           // 38.2° — window chord angle
  const startAng = Math.PI / 2 + a;      // 128.2°  (point (−17.3, 22))
  const endAng   = Math.PI / 2 - a + Math.PI * 2; // 411.8° (point (17.3, 22))
  const s = new THREE.Shape();
  /* main arc: whole circle minus the front window arc (CCW, the long way) */
  s.absarc(0, 0, R, startAng, endAng, false);
  /* rectangular head-window notch, 14 wide × 6 deep at the front */
  s.lineTo(7, 22);
  s.lineTo(7, 28);
  s.lineTo(-7, 28);
  s.lineTo(-7, 22);
  s.lineTo(-R * Math.cos(startAng), R * Math.sin(startAng)); // back to arc start
  s.closePath();
  s.holes.push(circleHole(0, 0, 7));     // central hub opening
  return s;
}
function createLiner(fill) {
  const g = new THREE.Group();
  const mesh = extrudeFlat(linerShape(), 0.05, fill);   // very thin
  addEdgedMesh(mesh, g);
  return g;
}

/* ============================================================================
   3.3 MAGNETIC DISK — the only part with a solid fill
   ============================================================================ */
function createDisk() {
  const g = new THREE.Group();
  const disk = new THREE.Mesh(new THREE.CylinderGeometry(22, 22, 0.3, 64), diskFill);
  addEdgedMesh(disk, g, deepEdgeMat);    // deep-blue edges
  /* a few short slanted lines = data-track highlights on the surface */
  [[[-14, 6], [-6, 14]], [[2, 16], [10, 8]], [[12, -10], [18, -4]]].forEach(([a, b]) => {
    g.add(makeLine(edgeMat,
      new THREE.Vector3(a[0], 0.16, a[1]),
      new THREE.Vector3(b[0], 0.16, b[1])));
  });
  return g;
}

/* ============================================================================
   3.4 HUB — central metal disc with circular + square spindle keyway
   ============================================================================ */
function createHub() {
  const g = new THREE.Group();
  const body = new THREE.Mesh(new THREE.CylinderGeometry(5, 5, 0.4, 48), hubFill);
  addEdgedMesh(body, g);
  /* cap disc on top with REAL holes: central circle + offset square */
  const capShape = new THREE.Shape();
  capShape.absarc(0, 0, 4.6, 0, Math.PI * 2, false);
  capShape.closePath();
  capShape.holes.push(circleHole(0, 0, 2.3));          // central round hole
  capShape.holes.push(rectHole(2.1, -0.8, 3.7, 0.8));  // square drive-pin hole
  const cap = extrudeFlat(capShape, 0.05, hubFill);
  cap.position.y = 0.2;
  addEdgedMesh(cap, g);
  return g;
}

/* ============================================================================
   3.7 SHUTTER — OPAQUE metal plate with a single left-biased rectangular slot
   ============================================================================ */
function createShutter() {
  const g = new THREE.Group();
  const shape = new THREE.Shape();
  /* plate 22 (X) × 16 (Z, local y 14..30 → world z −30..−14) */
  shape.moveTo(-11, 14); shape.lineTo(11, 14); shape.lineTo(11, 30); shape.lineTo(-11, 30);
  shape.closePath();
  /* window: SAME shared rect as the shells — short side (6) ∥ long edge (22),
     long axis (14) ⟂ shutter long axis, biased LEFT (x −10..−4) */
  shape.holes.push(rectHole(HEAD_SLOT.x0, -HEAD_SLOT.z1, HEAD_SLOT.x1, -HEAD_SLOT.z0));
  const plate = extrudeFlat(shape, 1, shutterFill);    // OPAQUE, never ghosted
  addEdgedMesh(plate, g);
  g.position.set(0, -1.5, -22);          // embedded in bottom-shell slot
  return g;
}

/* ============================================================================
   WRITE PROTECT TAB — small block at the bottom shell's back-right
   ============================================================================ */
function createTab() {
  const g = new THREE.Group();
  const box = new THREE.Mesh(new THREE.BoxGeometry(3, 2, 3), tabFill);
  addEdgedMesh(box, g);
  g.position.set(24, -1, 24);
  return g;
}

/* ------------------------- build & place parts ----------------------------- */
const topShell    = createTopShell();
const linerUp     = createLiner(linerFillUp);
const diskGroup   = createDisk();
const hubGroup    = createHub();
const linerLo     = createLiner(linerFillLo);
const bottomShell = createBottomShell();
const shutterGroup = createShutter();
const tabGroup    = createTab();

[topShell, linerUp, diskGroup, hubGroup, linerLo, bottomShell, shutterGroup, tabGroup]
  .forEach((o) => scene.add(o));

/* ============================================================================
   ANIMATION: part registry (dual-state positions + opacity targets, spec §6.3)
   ============================================================================ */
const parts = [];
function registerPart(group, from, to, delay, fillMats, fromOp, toOp) {
  parts.push({
    group,
    from: new THREE.Vector3(...from),
    to:   new THREE.Vector3(...to),
    delay,
    collapseDelay: MAX_DELAY - delay,    // collapse stacks bottom-first
    fillMats, fromOp, toOp
  });
}
function setupParts() {
  /*        group          assembled→exploded           delay   materials        assembledOp → explodedOp */
  registerPart(topShell,    [0, 1.5, 0],  [0, 45, 0],      0,        [topShellFill],    1, 0.08);
  registerPart(linerUp,     [0, 1.0, 0],  [0, 30, 0],      STAGGER,  [linerFillUp],     1, 0.08);
  registerPart(hubGroup,    [0, 0.7, 0],  [0, 18, 0],      STAGGER*2,[hubFill],         1, 0.08);
  registerPart(diskGroup,   [0, 0.5, 0],  [0, 15, 0],      STAGGER*3,[diskFill],        1, 0.50);
  registerPart(linerLo,     [0, 0.0, 0],  [0,  0, 0],      STAGGER*4,[linerFillLo],     1, 0.08);
  registerPart(bottomShell, [0,-1.5, 0],  [0,-15, 0],      STAGGER*5,[bottomShellFill], 1, 0.08);
  registerPart(shutterGroup,[0,-1.5,-22], [-30,-15,-30],   STAGGER*6,[],               1, 1);   // OPAQUE always
  registerPart(tabGroup,    [24,-1, 24],  [30,-15, 30],    STAGGER*7,[tabFill],         1, 0.08);
}
setupParts();

/* ============================================================================
   ANNOTATIONS: dashed assembly guides (spec §4)
   ============================================================================ */
const dashedGuides = [];
function dashedLine(a, b) {
  const g = new THREE.BufferGeometry().setFromPoints([a, b]);
  const m = new THREE.LineDashedMaterial({
    color: BLUE, dashSize: 2.5, gapSize: 2, transparent: true, opacity: 0
  });
  const l = new THREE.Line(g, m);
  l.computeLineDistances();              // required for dashed rendering
  scene.add(l);
  dashedGuides.push(l);
  return l;
}
/* 4 vertical guides through the chamfer-corner positions, Top → Bottom shell */
[[26, 26], [-26, 26], [26, -26], [-26, -26]].forEach(([x, z]) => {
  dashedLine(new THREE.Vector3(x, -17, z), new THREE.Vector3(x, 46, z));
});
/* oblique guides: SHUTTER → bottom shell, WRITE PROTECT TAB → bottom shell */
dashedLine(new THREE.Vector3(-30, -15, -30), new THREE.Vector3(0, -15, -22));
dashedLine(new THREE.Vector3(30, -15, 30),  new THREE.Vector3(24, -15, 24));

/* ============================================================================
   ANNOTATIONS: CSS2D labels + leader lines (spec §4)
   ============================================================================ */
const labels = [];
function addLabel(text, anchor, labelPos, order) {
  const el = document.createElement('div');
  el.className = 'dsh-label';
  el.textContent = text;
  const obj = new THREE.CSS2DObject(el);
  obj.position.set(...labelPos);
  scene.add(obj);
  const leader = makeLine(
    new THREE.LineBasicMaterial({ color: BLUE, transparent: true, opacity: 0 }),
    new THREE.Vector3(...anchor), new THREE.Vector3(...labelPos));
  scene.add(leader);
  labels.push({ obj, leader, order });
}
addLabel('TOP SHELL',           [22, 45, 14],     [32, 49, 18],     0);
addLabel('HD NOTCH',            [-26, 46, 26],    [-34, 49, 30],    1);
addLabel('DUST LINER (UPPER)',  [-18, 30, 12],    [-30, 31, 16],    2);
addLabel('HUB',                 [4, 18, 4],       [-26, 19, 10],    3);
addLabel('MAGNETIC DISK',       [16, 15, 10],     [28, 16, 14],     4);
addLabel('DUST LINER (LOWER)',  [-18, 0, 12],     [-30, 1, 16],     5);
addLabel('BOTTOM SHELL',        [22, -15, 14],    [32, -11, 18],    6);
addLabel('LIFTER',              [0, -15, -8],     [-24, -11, -10],  7);
addLabel('SHUTTER SPRING',      [1, -15, -28],    [-22, -11, -26],  8);
addLabel('WRITE PROTECT NOTCH', [25.5, -15, 25.5],[34, -11, 30],    9);
addLabel('SHUTTER',             [-30, -15, -30],  [-43, -10, -38],  10);
addLabel('WRITE PROTECT TAB',   [30, -15, 30],    [40, -10, 38],    11);

/* ============================================================================
   ANIMATION: generic tweens (for line / dashed-material opacity)
   ============================================================================ */
const tweens = [];
function addTween(obj, key, from, to, dur, delay = 0) {
  tweens.push({ obj, key, from, to, dur, start: performance.now() + delay });
}
function updateTweens(now) {
  for (let i = tweens.length - 1; i >= 0; i--) {
    const tw = tweens[i];
    const p = clamp01((now - tw.start) / tw.dur);
    tw.obj[tw.key] = tw.from + (tw.to - tw.from) * easeInOutCubic(p);
    if (p >= 1) tweens.splice(i, 1);
  }
}

/* ============================================================================
   ANIMATION: state machine  (spec §6.1)
   ============================================================================ */
let animState = 'assembled';   // 'assembled' | 'exploding' | 'exploded' | 'collapsing'
let animStart = 0;

function applyPartProgress(t) {
  const e = easeInOutCubic(clamp01(t));
  for (const p of parts) {
    p.group.position.set(lerp(p.from.x, p.to.x, e),
                         lerp(p.from.y, p.to.y, e),
                         lerp(p.from.z, p.to.z, e));
    for (const m of p.fillMats) {
      m.opacity = lerp(p.fromOp, p.toOp, e);
      m.depthWrite = m.opacity > 0.95;   // opaque writes depth; ghosts don't
    }
  }
}

/* per-frame: advance positions + material opacity with one shared progress,
   staggered per part (spec §6.3) */
function updateAnimation(now) {
  if (animState !== 'exploding' && animState !== 'collapsing') return;
  const elapsed = now - animStart;
  if (elapsed >= DURATION) {
    if (animState === 'exploding') {
      animState = 'exploded';
      applyPartProgress(1);
      showLabels();                      // dashed guides → labels, staggered
    } else {
      animState = 'assembled';
      applyPartProgress(0);
    }
    setHint();
    return;
  }
  for (const p of parts) {
    const t = animState === 'exploding'
      ? clamp01((elapsed - p.delay) / (DURATION - p.delay))
      : 1 - clamp01((elapsed - p.collapseDelay) / (DURATION - p.collapseDelay));
    const e = easeInOutCubic(t);
    p.group.position.set(lerp(p.from.x, p.to.x, e),
                         lerp(p.from.y, p.to.y, e),
                         lerp(p.from.z, p.to.z, e));
    for (const m of p.fillMats) {
      m.opacity = lerp(p.fromOp, p.toOp, e);
      m.depthWrite = m.opacity > 0.95;
    }
  }
}

/* ============================================================================
   ANIMATION: explode / collapse triggers (spec §6.2)
   ============================================================================ */
function triggerExplode() {
  if (animState !== 'assembled') return;
  hideLabels();
  animState = 'exploding';
  animStart = performance.now();
  setHint();
}
function triggerCollapse() {
  if (animState !== 'exploded') return;
  hideLabels();                          // labels / guides fade first (~0.3s)
  animState = 'collapsing';
  animStart = performance.now() + 300;   // then collapse (spec §6.4)
  setHint();
}

/* ============================================================================
   ANNOTATIONS: show / hide sequencing (spec §6.4)
   ============================================================================ */
let labelTimers = [];
function showLabels() {
  labelTimers.forEach(clearTimeout); labelTimers = [];
  /* t+200ms: 4 vertical guides fade in (easeInOutCubic, 400ms) */
  labelTimers.push(setTimeout(() => {
    dashedGuides.forEach((l) => addTween(l.material, 'opacity', 0, 1, 400));
  }, 200));
  /* t+400ms: labels top→bottom, one every 60ms; leader lines follow */
  labelTimers.push(setTimeout(() => {
    const sorted = [...labels].sort((a, b) => a.order - b.order);
    sorted.forEach((lb, i) => labelTimers.push(setTimeout(() => {
      lb.obj.element.style.opacity = 1;              // CSS transition fades it in
      addTween(lb.leader.material, 'opacity', 0, 1, 400);
    }, i * 60)));
  }, 400));
}
function hideLabels() {
  labelTimers.forEach(clearTimeout); labelTimers = [];
  labels.forEach((lb) => {
    lb.obj.element.style.opacity = 0;
    addTween(lb.leader.material, 'opacity', 1, 0, 300);
  });
  dashedGuides.forEach((l) => addTween(l.material, 'opacity', 1, 0, 300));
}

/* ============================================================================
   CONTROLS — OrbitControls with DCC-style mouse mapping (spec §1)
   ============================================================================ */
function setupControls() {
  const controls = new OrbitControls(camera, renderer.domElement);
  controls.enableDamping = true;
  controls.dampingFactor = 0.08;
  controls.enableRotate = true;
  controls.enablePan = true;
  controls.enableZoom = true;            // wheel zoom stays ON
  /* LMB rotate · MMB dolly · RMB pan */
  controls.mouseButtons.LEFT   = THREE.MOUSE.ROTATE;
  controls.mouseButtons.MIDDLE = THREE.MOUSE.DOLLY;
  controls.mouseButtons.RIGHT  = THREE.MOUSE.PAN;
  /* orthographic zoom limits (perspective would use min/maxDistance) */
  controls.minZoom = 0.3;
  controls.maxZoom = 3.5;
  controls.zoomSpeed = 1.1;
  /* keep the floppy from being panned out of view */
  controls.addEventListener('change', () => {
    const MAX_T = 130;
    if (controls.target.length() > MAX_T) {
      const v = new THREE.Vector3().subVectors(camera.position, controls.target);
      controls.target.setLength(MAX_T);
      camera.position.copy(controls.target).add(v);
    }
  });
  /* right-drag pan must not open the browser context menu */
  renderer.domElement.addEventListener('contextmenu', (e) => e.preventDefault());
  return controls;
}
const controls = setupControls();

/* ------------------------- keyboard input (spec §6.2) ---------------------- */
window.addEventListener('keydown', (e) => {
  if (e.code === 'Space' || e.key === ' ') {
    e.preventDefault();
    if (animState === 'assembled') triggerExplode();
    else if (animState === 'exploded') triggerCollapse();
    /* ignore Space while an animation is running */
  }
});

/* ------------------------- hint UI (spec §6.5) ----------------------------- */
const hintEl = document.getElementById('hint');
function setHint() {
  hintEl.classList.toggle('hidden', animState !== 'assembled');
}
setHint();

/* ------------------------- resize ------------------------------------------ */
function onResize() {
  const w = window.innerWidth, h = window.innerHeight;
  camera.left = -FRUSTUM * (w / h);
  camera.right = FRUSTUM * (w / h);
  camera.top = FRUSTUM;
  camera.bottom = -FRUSTUM;
  camera.updateProjectionMatrix();
  renderer.setSize(w, h);
  labelRenderer.setSize(w, h);
}
window.addEventListener('resize', onResize);
onResize();

/* ------------------------- render loop ------------------------------------- */
function animate(now) {
  requestAnimationFrame(animate);
  updateAnimation(now);
  updateTweens(now);
  controls.update();
  renderer.render(scene, camera);
  labelRenderer.render(scene, camera);
}
requestAnimationFrame(animate);
</script>
</body>
</html>
"}

