// Stubs DOM / WebGL / rAF / clock, then drives the animation state machine.
import * as THREE from 'three';
import assert from 'node:assert/strict';

// ---------- controllable clock ----------
let clock = 0;
globalThis.performance = { now: () => clock };

// ---------- stub DOM ----------
const listeners = {};
function makeCtx() {
  return new Proxy({}, {
    get(t, p) { if (p === 'canvas') return {}; return () => undefined; },
    set() { return true; },
  });
}
const stubDoc = {
  createElement: (tag) => makeEl(tag),
  getElementById: () => makeEl('div'),
  addEventListener: () => {},
};
function makeEl(tag) {
  const el = {
    tagName: tag, style: {}, className: '', textContent: '',
    children: [],
    appendChild(c) { el.children.push(c); return c; },
    classList: { toggle() {}, add() {}, remove() {} },
    addEventListener: () => {},
    setPointerCapture: () => {},
    releasePointerCapture: () => {},
    ownerDocument: stubDoc,
    getBoundingClientRect: () => ({ width: 0, height: 0 }),
  };
  if (tag === 'canvas') el.getContext = () => makeCtx();
  return el;
}
globalThis.document = stubDoc;
globalThis.window = {
  innerWidth: 1280, innerHeight: 800, devicePixelRatio: 1,
  addEventListener: (type, fn) => { listeners[type] = fn; },
};

// ---------- stub renderers ----------
class FakeRenderer {
  constructor() { this.domElement = makeEl('canvas'); }
  setPixelRatio() {} setSize() {} setClearColor() {} render() {}
}
THREE.WebGLRenderer = FakeRenderer;

// ---------- capture rAF ----------
let rafCb = null;
globalThis.requestAnimationFrame = (fn) => { rafCb = fn; return 1; };

// ---------- load the module ----------
await import('./floppy_mod.mjs');
const t = globalThis.__test;
const space = { code: 'Space', key: ' ', preventDefault() {} };

function step(now) { clock = now; rafCb(now); }

console.log('--- module loaded, scene children:', t.scene.children.length);

// ---------- 1. initial assembled state ----------
assert.equal(t.getState(), 'assembled');
assert.equal(t.topShell.position.y, 1.5);
assert.equal(t.bottomShell.position.y, -1.5);
assert.equal(t.shutterGroup.position.x, 0);
assert.equal(t.tabGroup.position.z, 24);
assert.equal(t.topShellFill.opacity, 1);
assert.equal(t.diskFill.opacity, 1);
assert.equal(t.shutterFill.opacity, 1);
console.log('OK 1: assembled state, all parts at assembledY, fills opaque (1)');

// ---------- 2. explode (mid-flight) ----------
listeners.keydown(space);
assert.equal(t.getState(), 'exploding');
step(1500); // topShell t=0.5 -> ease 0.5
const yMid = t.topShell.position.y;
assert.ok(yMid > 10 && yMid < 35, `top shell mid-y ${yMid}`);
const opMid = t.topShellFill.opacity;
assert.ok(opMid > 0.2 && opMid < 0.9, `top shell mid-opacity ${opMid}`);
assert.equal(t.diskFill.opacity, 1, 'disk (delay 240ms) not started yet');
console.log('OK 2: exploding mid-flight, positions+opacity lerping with stagger');

// ---------- 3. explode finished ----------
step(3000);
assert.equal(t.getState(), 'exploded');
assert.ok(Math.abs(t.topShell.position.y - 45) < 1e-6);
assert.ok(Math.abs(t.bottomShell.position.y + 15) < 1e-6);
assert.ok(Math.abs(t.shutterGroup.position.x + 30) < 1e-6);
assert.ok(Math.abs(t.shutterGroup.position.z + 30) < 1e-6);
assert.ok(Math.abs(t.tabGroup.position.x - 30) < 1e-6);
assert.ok(Math.abs(t.tabGroup.position.z - 30) < 1e-6);
assert.ok(Math.abs(t.topShellFill.opacity - 0.08) < 1e-6);
assert.ok(Math.abs(t.diskFill.opacity - 0.5) < 1e-6);
assert.equal(t.shutterFill.opacity, 1, 'shutter stays OPAQUE');
console.log('OK 3: exploded — targets reached, shutter opaque, disk 0.5, fills 0.08');

// ---------- 4. collapse start has 300ms label-fade delay ----------
listeners.keydown(space);
assert.equal(t.getState(), 'collapsing');
step(3200); // animStart = 3000+300 = 3300 -> elapsed < 0 -> still exploded
assert.ok(Math.abs(t.topShell.position.y - 45) < 1e-6, 'parts hold during fade-out window');
console.log('OK 4: collapsing holds position during 300ms label fade-out');

// ---------- 5. collapse mid-flight ----------
step(5000); // elapsed 1700ms; bottomShell collapseDelay=160 -> t~0.46
const yBotMid = t.bottomShell.position.y;
assert.ok(yBotMid > -14 && yBotMid < -3, `bottom shell mid-y ${yBotMid}`);
assert.ok(t.bottomShellFill.opacity > 0.2, 'fill returning toward 1');
console.log('OK 5: collapsing mid-flight, parts stacking bottom-first');

// ---------- 6. collapse finished ----------
step(6300); // elapsed 3000 >= DURATION
assert.equal(t.getState(), 'assembled');
assert.ok(Math.abs(t.topShell.position.y - 1.5) < 1e-6);
assert.ok(Math.abs(t.topShellFill.opacity - 1) < 1e-6);
assert.ok(Math.abs(t.diskFill.opacity - 1) < 1e-6);
assert.ok(Math.abs(t.shutterGroup.position.x) < 1e-6);
console.log('OK 6: assembled again, all opacity back to 1');

// ---------- 7. label / guide wiring ----------
assert.equal(t.labels.length, 12, '12 CSS2D labels');
assert.equal(t.dashedGuides.length, 6, '4 vertical + 2 oblique dashed guides');
t.labels.forEach((l) => {
  assert.ok(l.obj.isCSS2DObject, 'label is CSS2DObject');
  assert.equal(l.obj.element.style.opacity, '0', 'labels start hidden');
});
console.log('OK 7: 12 labels + 6 dashed guides, labels hidden initially');

