const topShellEdges = t.topShell.children.filter((c) => c.isLineSegments);
assert.ok(topShellEdges.length >= 4, `top shell has edged sub-parts (${topShellEdges.length})`);
assert.ok(t.scene.children.filter((c) => c.type === 'Group').length >= 8, '8 part groups');
console.log('OK 8: compound groups + edged sub-parts present');

console.log('\nALL CHECKS PASSED');
