// camera and writes PNG snapshots (assembled + exploded) for visual review.
import * as THREE from 'three';
import { deflateSync, crc32 } from 'node:zlib';
import { writeFileSync } from 'node:fs';

// ---- stubs (same as run.mjs) ----
let clock = 0;
globalThis.performance = { now: () => clock };
const listeners = {};
function makeCtx() {
  return new Proxy({}, {
    get(t, p) { if (p === 'canvas') return {}; return () => undefined; },
    set() { return true; },
  });
}
const stubDoc = {
  createElement: (tag) => makeEl(tag),
  getElementById: () => makeEl('div'),
  addEventListener: () => {},
};
function makeEl(tag) {
  const el = {
    tagName: tag, style: {}, className: '', textContent: '', children: [],
    appendChild(c) { el.children.push(c); return c; },
    classList: { toggle() {}, add() {}, remove() {} },
    addEventListener: () => {},
    setAttribute: () => {}, getAttribute: () => null, removeAttribute: () => {},
    setPointerCapture: () => {}, releasePointerCapture: () => {},
    ownerDocument: stubDoc,
    getBoundingClientRect: () => ({ width: 0, height: 0 }),
  };
  if (tag === 'canvas') el.getContext = () => makeCtx();
  return el;
}
globalThis.document = stubDoc;
globalThis.window = { innerWidth: 1280, innerHeight: 800, devicePixelRatio: 1, addEventListener: (t, f) => { listeners[t] = f; } };
let rafCb = null;
globalThis.requestAnimationFrame = (fn) => { rafCb = fn; return 1; };

await import('./floppy_mod.mjs');
const t = globalThis.__test;
const space = { code: 'Space', key: ' ', preventDefault() {} };
const step = (now) => { clock = now; rafCb(now); };

// ---- tiny PNG encoder (8-bit RGBA) ----
function pngChunk(type, data) {
  const len = Buffer.alloc(4); len.writeUInt32BE(data.length);
  const tb = Buffer.from(type, 'ascii');
  const cb = Buffer.alloc(4); cb.writeUInt32BE(crc32(Buffer.concat([tb, data])) >>> 0);
  return Buffer.concat([len, tb, data, cb]);
}
function encodePNG(w, h, rgba) {
  const stride = w * 4;
  const raw = Buffer.alloc((stride + 1) * h);
  for (let y = 0; y < h; y++) {
    raw[y * (stride + 1)] = 0;
    Buffer.from(rgba.buffer, y * stride, stride).copy(raw, y * (stride + 1) + 1);
  }
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(w, 0); ihdr.writeUInt32BE(h, 4);
  ihdr[8] = 8; ihdr[9] = 6;
  const idat = deflateSync(raw, { level: 9 });
  return Buffer.concat([
    Buffer.from([0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A]),
    pngChunk('IHDR', ihdr), pngChunk('IDAT', idat), pngChunk('IEND', Buffer.alloc(0)),
  ]);
}

// ---- raster buffer + line drawing ----
const W = 1280, H = 800;
const buf = new Uint8Array(W * H * 4);
function fill(c) { for (let i = 0; i < W * H; i++) { buf[i * 4] = c[0]; buf[i * 4 + 1] = c[1]; buf[i * 4 + 2] = c[2]; buf[i * 4 + 3] = 255; } }
function setPx(x, y, c) {
  if (x < 0 || x >= W || y < 0 || y >= H) return;
  const i = (y * W + x) * 4;
  buf[i] = c[0]; buf[i + 1] = c[1]; buf[i + 2] = c[2];
}
const BG = [0xF5, 0xF7, 0xFA], BLUE = [0x41, 0x69, 0xE1], DBLUE = [0x2b, 0x4f, 0xd8];
function linePx(a, b, c) {
  const x0 = a[0], y0 = a[1], x1 = b[0], y1 = b[1];
  const dx = Math.abs(x1 - x0), dy = -Math.abs(y1 - y0);
  const sx = x0 < x1 ? 1 : -1, sy = y0 < y1 ? 1 : -1;
  let err = dx + dy, x = x0, y = y0;
  for (;;) {
    setPx(x, y, c); setPx(x + 1, y, c); setPx(x, y + 1, c);
    if (x === x1 && y === y1) break;
    const e2 = 2 * err;
    if (e2 >= dy) { err += dy; x += sx; }
    if (e2 <= dx) { err += dx; y += sy; }
  }
}

// ---- collect wireframe segments from the scene ----
function collectLines() {
  const segs = [];
  t.scene.updateMatrixWorld(true);
  t.scene.traverse((o) => {
    if (!(o.isLine || o.isLineSegments)) return;
    if (o.material && o.material.opacity === 0) return;
    const pos = o.geometry.attributes.position;
    const local = [];
    for (let i = 0; i < pos.count; i++) local.push(new THREE.Vector3().fromBufferAttribute(pos, i));
    segs.push({
      local,
      dashed: !!(o.material && o.material.isLineDashedMaterial),
      color: (o.material && o.material.color) ? o.material.color.getHex() : 0x4169E1,
      matrix: o.matrixWorld,
    });
  });
  return segs;
}

// ---- project + draw ----
function renderFrame(file, labelPts = []) {
  fill(BG);
  const cam = t.camera;
  cam.updateMatrixWorld(true);
  cam.updateProjectionMatrix();
  const v = new THREE.Vector4();
  const proj = (p) => {
    v.set(p.x, p.y, p.z, 1);
    v.applyMatrix4(cam.matrixWorldInverse);
    v.applyMatrix4(cam.projectionMatrix);
    const nx = v.x / v.w, ny = v.y / v.w;
    return [Math.round((nx + 1) * 0.5 * W), Math.round((1 - ny) * 0.5 * H)];
  };
  const world = new THREE.Vector3();
  for (const s of collectLines()) {
    const c = s.color === 0x2b4fd8 ? DBLUE : BLUE;
    const pts = s.local.map((p) => { world.copy(p).applyMatrix4(s.matrix); return proj(world); });
    if (s.dashed) {
      for (let i = 0; i < pts.length - 1; i++) {
        // dash along the segment: 3 on / 2 off
        const a = pts[i], b = pts[i + 1];
        const d = Math.hypot(b[0] - a[0], b[1] - a[1]) || 1;
        const n = Math.ceil(d / 5);
        for (let k = 0; k < n; k++) {
          if (k % 2 === 0) {
            const t0 = k / n, t1 = Math.min((k + 1) / n, 1);
            linePx([a[0] + (b[0] - a[0]) * t0, a[1] + (b[1] - a[1]) * t0],
