          }
        }
      }
    } else {
      for (let i = 0; i < pts.length - 1; i++) linePx(pts[i], pts[i + 1], c);
    }
  }
  // label anchor crosses (small red)
  for (const [x, y] of labelPts) {
    const p = proj(new THREE.Vector3(x, y, 0));
    for (let dx = -4; dx <= 4; dx++) { setPx(p[0] + dx, p[1], [0xC0, 0x30, 0x30]); setPx(p[0], p[1] + dx, [0xC0, 0x30, 0x30]); }
  }
  writeFileSync(file, encodePNG(W, H, buf));
  console.log('wrote', file);
}

// ---- frame 1: assembled ----
t.labels.forEach((l) => (l.obj.element.style.opacity = 0));
t.dashedGuides.forEach((l) => (l.material.opacity = 0));
renderFrame('assembled.png');

// ---- explode, force annotations visible, frame 2 ----
listeners.keydown(space);
step(3000);
t.dashedGuides.forEach((l) => (l.material.opacity = 1));
t.labels.forEach((l) => (l.leader.material.opacity = 1));
renderFrame('exploded.png', [[0, 45], [0, 30], [0, 18], [0, 15], [0, 0], [0, -15]]);
", "file_path": "/tmp/floppy-check/render_png.mjs"}

