{"content": "// Layout report: projects key features with the module's own camera and
// verifies composition bounds + head-slot alignment on screen.
import * as THREE from 'three';
import { appendFileSync } from 'node:fs';

let clock = 0;
globalThis.performance = { now: () => clock };
const listeners = {};
function makeCtx() { return new Proxy({}, { get(t, p) { if (p === 'canvas') return {}; return () => undefined; }, set() { return true; } }); }
const stubDoc = {
  createElement: (tag) => makeEl(tag),
  getElementById: () => makeEl('div'),
  addEventListener: () => {},
};
function makeEl(tag) {
  const el = {
    tagName: tag, style: {}, className: '', textContent: '', children: [],
    appendChild(c) { el.children.push(c); return c; },
    classList: { toggle() {}, add() {}, remove() {} },
    addEventListener: () => {},
    setAttribute: () => {}, getAttribute: () => null, removeAttribute: () => {},
    setPointerCapture: () => {}, releasePointerCapture: () => {},
    ownerDocument: stubDoc, getBoundingClientRect: () => ({ width: 0, height: 0 }),
  };
  if (tag === 'canvas') el.getContext = () => makeCtx();
  return el;
}
globalThis.document = stubDoc;
globalThis.window = { innerWidth: 1280, innerHeight: 800, devicePixelRatio: 1, addEventListener: (t, f) => { listeners[t] = f; } };
let rafCb = null;
globalThis.requestAnimationFrame = (fn) => { rafCb = fn; return 1; };

await import('./floppy_mod.mjs');
const t = globalThis.__test;
const space = { code: 'Space', key: ' ', preventDefault() {} };
const step = (now) => { clock = now; rafCb(now); };

const W = 1280, H = 800;
const cam = t.camera;
cam.updateMatrixWorld(true);
cam.updateProjectionMatrix();
const v = new THREE.Vector4();
const proj = (p) => {
  v.set(p.x, p.y, p.z, 1);
  v.applyMatrix4(cam.matrixWorldInverse);
  v.applyMatrix4(cam.projectionMatrix);
  return [((v.x / v.w) + 1) * 0.5 * W, (1 - (v.y / v.w)) * 0.5 * H];
};
const P = (x, y, z) => proj(new THREE.Vector3(x, y, z));
const fmt = (a) => `(${a[0].toFixed(0)}, ${a[1].toFixed(0)})`;
let report = '';

const box = { x0: 1e9, y0: 1e9, x1: -1e9, y1: -1e9 };
function acc(p) { box.x0 = Math.min(box.x0, p[0]); box.y0 = Math.min(box.y0, p[1]); box.x1 = Math.max(box.x1, p[0]); box.y1 = Math.max(box.y1, p[1]); }

// --- assembled frame ---
report += '== ASSEMBLED ==\n';
const assemPts = [];
[['topShell', [0, 1.5, 0]], ['linerUp', [0, 1, 0]], ['disk', [0, 0.5, 0]], ['hub', [0, 0.7, 0]],
 ['linerLo', [0, 0, 0]], ['bottomShell', [0, -1.5, 0]], ['shutter', [0, -1.5, -22]], ['tab', [24, -1, 24]]]
  .forEach(([n, p]) => { const s = P(...p); acc(s); assemPts.push(`${n}: ${fmt(s)}`); });
report += assemPts.join('\n') + '\n';
report += `bounds ${fmt([box.x0, box.y0])} .. ${fmt([box.x1, box.y1])}  inside=${box.x0 >= 0 && box.y0 >= 0 && box.x1 <= W && box.y1 <= H}\n`;

// --- explode ---
listeners.keydown(space);
step(3000);
cam.updateMatrixWorld(true);
cam.updateProjectionMatrix();
report += '\n== EXPLODED ==\n';
const expPts = [];
[['topShell', [0, 45, 0]], ['linerUp', [0, 30, 0]], ['hub', [0, 18, 0]], ['disk', [0, 15, 0]],
 ['linerLo', [0, 0, 0]], ['bottomShell', [0, -15, 0]], ['shutter', [-30, -15, -30]], ['tab', [30, -15, 30]]]
  .forEach(([n, p]) => { const s = P(...p); acc(s); expPts.push(`${n}: ${fmt(s)}`); });
report += expPts.join('\n') + '\n';

// label positions
report += 'labels:\n';
t.labels.forEach((l) => { const s = P(l.obj.position.x, l.obj.position.y, l.obj.position.z); acc(s); report += `  ${l.obj.element.textContent}: ${fmt(s)}\n`; });

// --- head-slot alignment: project the 4 corners of the shared rect at each level ---
report += '\nhead-slot rects (should coincide on screen when aligned in XZ):\n';
function slotRect(y, name) {
  const c = [[HEAD_SLOT.x0, y, HEAD_SLOT.z0], [HEAD_SLOT.x1, y, HEAD_SLOT.z0],
             [HEAD_SLOT.x1, y, HEAD_SLOT.z1], [HEAD_SLOT.x0, y, HEAD_SLOT.z1]].map((p) => P(...p));
  const xs = c.map((p) => p[0]), ys = c.map((p) => p[1]);
  report += `  ${name} y=${y}: center ${fmt([(Math.min(...xs) + Math.max(...xs)) / 2, (Math.min(...ys) + Math.max(...ys)) / 2])} size ${((Math.max(...xs) - Math.min(...xs))).toFixed(1)}x${(Math.max(...ys) - Math.min(...ys)).toFixed(1)}\n`;
}
slotRect(46, 'topShell   ');   // top shell top surface (exploded)
slotRect(-14, 'bottomShell');  // bottom shell top surface (exploded)
slotRect(-15, 'shutter    ');  // shutter plate mid-plane

// vertical guides endpoints
report += '\nvertical guides:\n';
[[26, 26], [-26, 26], [26, -26], [-26, -26]].forEach(([x, z]) => {
  const a = P(x, -17, z), b = P(x, 46, z);
  acc(a); acc(b);
  report += `  (${x},${z}): ${fmt(a)} -> ${fmt(b)}\n`;
});

report += `\nOVERALL bounds ${fmt([box.x0, box.y0])} .. ${fmt([box.x1, box.y1])}  inside=${box.x0 >= 0 && box.y0 >= 0 && box.x1 <= W && box.y1 <= H}\n`;
appendFileSync('layout_report.txt', report);
console.log(report);
", "file_path": "/tmp/floppy-check/layout_report.mjs"}

